// Door profile drawings from Eagle Woodworking's product guide (eaglewoodworking.com/cabinet-doors/product-guide),
// which Eagle pointed us to as their door drawings: framing beads, MDF center panels and outside edges,
// as small grayscale images. Shown to customers without Eagle's name, like the rest of the customer side.
import type { ShopSettings } from './types';
import { outsideEdges, panelByCode, panelForFinish, styleById } from './eagle';

const img: Record<string, string> = {
"bead:5pc - A": "data:image/webp;base64,",
"bead:5pc - B": "data:image/webp;base64,",
"bead:5pc - C": "data:image/webp;base64,",
"bead:5pc - D": "data:image/webp;base64,",
"bead:5pc - E": "data:image/webp;base64,",
"bead:5pc - F": "data:image/webp;base64,",
"bead:5pc - G": "data:image/webp;base64,",
"bead:5pc - I": "data:image/webp;base64,",
"bead:5pc - L": "data:image/webp;base64,",
"bead:5pc - P": "data:image/webp;base64,",
"bead:2pc - A": "data:image/webp;base64,",
"bead:2pc - B": "data:image/webp;base64,",
"bead:2pc - C": "data:image/webp;base64,",
"bead:2pc - D": "data:image/webp;base64,",
"bead:2pc - E": "data:image/webp;base64,",
"bead:2pc - F": "data:image/webp;base64,",
"bead:2pc - G": "data:image/webp;base64,",
"panel:MDF-01": "data:image/webp;base64,",
"panel:MDF-02": "data:image/webp;base64,",
"panel:MDF-03": "data:image/webp;base64,",
"panel:MDF-04": "data:image/webp;base64,",
"panel:MDF-05": "data:image/webp;base64,",
"panel:MDF-06": "data:image/webp;base64,",
"panel:MDF-07": "data:image/webp;base64,",
"panel:MDF-08": "data:image/webp;base64,",
"panel:MDF-09": "data:image/webp;base64,",
"panel:MDF-10": "data:image/webp;base64,",
"edge:E-01": "data:image/webp;base64,",
"edge:E-02": "data:image/webp;base64,",
"edge:E-03": "data:image/webp;base64,"
};

export interface DoorDrawing { what: 'Framing bead' | 'Center panel' | 'Outside edge'; label: string; src: string }

/** The drawings for a job's doors: its framing bead, center panel and outside edge, where Eagle has one. */
export function doorDrawings(s: ShopSettings): DoorDrawing[] {
  const style = styleById(s.doorStyleId);
  const out: DoorDrawing[] = [];
  if (style.bead && img[`bead:${style.bead}`]) out.push({ what: 'Framing bead', label: style.name, src: img[`bead:${style.bead}`] });
  if (style.panelChoice) { const p = panelByCode(s.centerPanel), src = img[`panel:${p.code}`] ?? img[`panel:${panelForFinish(p.code, 'paint')}`]; if (src) out.push({ what: 'Center panel', label: p.name, src }); }
  if (style.profile !== 'slab' && img[`edge:${s.outsideEdge}`]) out.push({ what: 'Outside edge', label: (outsideEdges.find((e) => e.code === s.outsideEdge)?.name ?? '').replace(/ - default$/, ''), src: img[`edge:${s.outsideEdge}`] });
  return out;
}
